local LA_SV_ProvokeNear = Inherit(CppObjectBase)
function LA_SV_ProvokeNear:Ctor()
self:GenerateBehavior()
self:AddRootComposite("LaxSequencer", self:InstanceLaxSequencer())
-- When the player sits within 1.5 km of its tail (the Provoke dispatcher's near band) the plane picks ONE defensive move,
-- weighted by its pilot rank and AI level. A RandomSelect never retries a pick that fails, so every pick here always
-- moves (P5, a harder tailed plane, 2026-10-29; tools/re/BEHAVIOUR_DIRECTOR.md unit 2): a gate that can fail sits under a
-- LaxSelector with its opposite gate over the fallback. Each pick stays under 5 s: 6 s in Provoke sets the stock
-- blackout (10 s of level flight). How a tree runs: tools/re/BEHAVIOUR_NATIVE_LOGIC.md 3-6; tools/checks/tailed_test.lua
-- walks every pick.
self:AddComposite("LaxSequencer", "Reaction", self:InstanceRandomSelect())
-- a hard break turn away from the pursuer, either side (every rank)
self:AddProbability("Reaction", "BreakW", self:InstanceWeightProbabilityPilotRank(10.0, 8.0, 6.0, 4.0, 3.0))
self:AddComposite("BreakW", "Break", self:InstanceRandomSelect())
self:AddComposite("Break", "BreakRight", self:InstanceSequencer())
self:AddTask("BreakRight", "BR_Roll", self:InstanceManeuverRoll(1.0, 90.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 0.2, false))
self:AddTask("BreakRight", "BR_Pitch", self:InstanceManeuverPitch(1.0, 60.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 2.5, false))
self:AddComposite("Break", "BreakLeft", self:InstanceSequencer())
self:AddTask("BreakLeft", "BL_Roll", self:InstanceManeuverRoll(-1.0, 90.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 0.2, false))
self:AddTask("BreakLeft", "BL_Pitch", self:InstanceManeuverPitch(1.0, 60.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 2.5, false))
-- brake-and-turn overshoot (rank 2+), only with the pursuer within 50 m when Provoke began (PursuerDistance 5000 cm, as
-- stock Provoke_0400_s gates it); farther out a 300 km/h turn only slows it down in front of the guns, so the same pick
-- breaks hard instead. The two gates are each other's opposite: when the decel's turn ends, the LaxSelector goes on to
-- its next child (a finished composite always lets its parent continue) and that gate fails, so exactly one runs.
self:AddProbability("Reaction", "DecelW", self:InstanceWeightProbabilityPilotRank(0.0, 2.0, 4.0, 6.0, 6.0))
self:AddComposite("DecelW", "DecelGate", self:InstanceLaxSelector())
self:AddDecorator("DecelGate", "DecelClose", self:InstanceDecoratorBlackboardFloat("PursuerDistance", 5000.0, EArithmeticKeyOperation.LessOrEqual, false))
self:AddComposite("DecelClose", "Decel", self:InstanceRandomSelect())
self:AddComposite("Decel", "DecelRight", self:InstanceSequencer())
self:AddTask("DecelRight", "DR_Roll", self:InstanceManeuverRoll(1.0, 90.0, "TargetActor", ELiveAIManeuverSpeedType.SpdConstant, 300.0, 0.5, false))
self:AddTask("DecelRight", "DR_Pitch", self:InstanceManeuverPitch(1.0, 60.0, "TargetActor", ELiveAIManeuverSpeedType.SpdConstant, 300.0, 2.0, false))
self:AddComposite("Decel", "DecelLeft", self:InstanceSequencer())
self:AddTask("DecelLeft", "DL_Roll", self:InstanceManeuverRoll(-1.0, 90.0, "TargetActor", ELiveAIManeuverSpeedType.SpdConstant, 300.0, 0.5, false))
self:AddTask("DecelLeft", "DL_Pitch", self:InstanceManeuverPitch(1.0, 60.0, "TargetActor", ELiveAIManeuverSpeedType.SpdConstant, 300.0, 2.0, false))
self:AddDecorator("DecelGate", "DecelFar", self:InstanceDecoratorBlackboardFloat("PursuerDistance", 5000.0, EArithmeticKeyOperation.Greater, false))
self:AddComposite("DecelFar", "DecelBreak", self:InstanceRandomSelect())
self:AddComposite("DecelBreak", "DecelBreakRight", self:InstanceSequencer())
self:AddTask("DecelBreakRight", "DBR_Roll", self:InstanceManeuverRoll(1.0, 90.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 0.2, false))
self:AddTask("DecelBreakRight", "DBR_Pitch", self:InstanceManeuverPitch(1.0, 60.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 2.5, false))
self:AddComposite("DecelBreak", "DecelBreakLeft", self:InstanceSequencer())
self:AddTask("DecelBreakLeft", "DBL_Roll", self:InstanceManeuverRoll(-1.0, 90.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 0.2, false))
self:AddTask("DecelBreakLeft", "DBL_Pitch", self:InstanceManeuverPitch(1.0, 60.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 2.5, false))
-- flares, then a break (rank 3+). ActivateFlares fails when no flare is ready (the pod reloads 25 s after a salvo), and a
-- failure ends the LaxSequencer it's in: in a LaxSequencer of its own, the break after it still comes.
self:AddProbability("Reaction", "FlareW", self:InstanceWeightProbabilityPilotRank(0.0, 0.0, 3.0, 4.0, 5.0))
self:AddComposite("FlareW", "FlareBreak", self:InstanceLaxSequencer())
self:AddComposite("FlareBreak", "FlareShot", self:InstanceLaxSequencer())
self:AddTask("FlareShot", "Flares", self:InstanceActivateFlares("PursuerActor", true))
self:AddComposite("FlareBreak", "FlareTurn", self:InstanceRandomSelect())
self:AddComposite("FlareTurn", "FlareRight", self:InstanceSequencer())
self:AddTask("FlareRight", "FR_Roll", self:InstanceManeuverRoll(1.0, 90.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 0.2, false))
self:AddTask("FlareRight", "FR_Pitch", self:InstanceManeuverPitch(1.0, 60.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 2.5, false))
self:AddComposite("FlareTurn", "FlareLeft", self:InstanceSequencer())
self:AddTask("FlareLeft", "FL_Roll", self:InstanceManeuverRoll(-1.0, 90.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 0.2, false))
self:AddTask("FlareLeft", "FL_Pitch", self:InstanceManeuverPitch(1.0, 60.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 2.5, false))
-- cobra bait (AI level 3+): a plane that can't post-stall (bCanManeuverPugachevsCobra off) breaks right instead
-- (the shape of stock Provoke_0002_s's cobra, with the opposite gate over the fallback)
self:AddProbability("Reaction", "CobraW", self:InstanceWeightProbabilityAILevel(0.0, 0.0, 5.0, 6.0, 7.0))
self:AddComposite("CobraW", "CobraBox", self:InstanceLaxSequencer())
self:AddComposite("CobraBox", "CobraOr", self:InstanceLaxSelector())
self:AddDecorator("CobraOr", "CanCobra", self:InstanceDecoratorCanCobra(true, true))
self:AddComposite("CanCobra", "CobraSeq", self:InstanceSequencer())
self:AddTask("CobraSeq", "Cobra", self:InstanceManeuverPugachevsCobra(false, false))
self:AddDecorator("CobraOr", "NoCobra", self:InstanceDecoratorCanCobra(false, false))
self:AddComposite("NoCobra", "CobraFallback", self:InstanceSequencer())
self:AddTask("CobraFallback", "CF_Roll", self:InstanceManeuverRoll(1.0, 90.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 0.2, false))
self:AddTask("CobraFallback", "CF_Pitch", self:InstanceManeuverPitch(1.0, 60.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 2.5, false))
-- kulbit bait (AI level 4+): without bCanManeuverKulbit it breaks left instead
self:AddProbability("Reaction", "KulbitW", self:InstanceWeightProbabilityAILevel(0.0, 0.0, 0.0, 5.0, 6.0))
self:AddComposite("KulbitW", "KulbitBox", self:InstanceLaxSequencer())
self:AddComposite("KulbitBox", "KulbitOr", self:InstanceLaxSelector())
self:AddDecorator("KulbitOr", "CanKulbit", self:InstanceDecoratorCanKulbit(true, true))
self:AddComposite("CanKulbit", "KulbitSeq", self:InstanceSequencer())
self:AddTask("KulbitSeq", "Kulbit", self:InstanceManeuverKulbit(false, false))
self:AddDecorator("KulbitOr", "NoKulbit", self:InstanceDecoratorCanKulbit(false, false))
self:AddComposite("NoKulbit", "KulbitFallback", self:InstanceSequencer())
self:AddTask("KulbitFallback", "KF_Roll", self:InstanceManeuverRoll(-1.0, 90.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 0.2, false))
self:AddTask("KulbitFallback", "KF_Pitch", self:InstanceManeuverPitch(1.0, 60.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 3000.0, 2.5, false))
-- scissors (AI level 4+): three reversals at 800 km/h
self:AddProbability("Reaction", "ScissorsW", self:InstanceWeightProbabilityAILevel(0.0, 0.0, 0.0, 4.0, 6.0))
self:AddComposite("ScissorsW", "ScissorsBox", self:InstanceLaxSequencer())
self:AddComposite("ScissorsBox", "Scissors", self:InstanceSequencer())
self:AddTask("Scissors", "S1_Roll", self:InstanceManeuverRoll(1.0, 90.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 800.0, 0.3, false))
self:AddTask("Scissors", "S1_Pitch", self:InstanceManeuverPitch(1.0, 45.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 800.0, 1.2, false))
self:AddTask("Scissors", "S2_Roll", self:InstanceManeuverRoll(-1.0, 180.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 800.0, 0.4, false))
self:AddTask("Scissors", "S2_Pitch", self:InstanceManeuverPitch(1.0, 45.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 800.0, 1.2, false))
self:AddTask("Scissors", "S3_Roll", self:InstanceManeuverRoll(1.0, 180.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 800.0, 0.4, false))
self:AddTask("Scissors", "S3_Pitch", self:InstanceManeuverPitch(1.0, 45.0, "PursuerActor", ELiveAIManeuverSpeedType.SpdConstant, 800.0, 1.2, false))
self:EndGenerateBehavior()
end
return LA_SV_ProvokeNear
